  --accent-to: #b74e91;
  --text: rgba(255, 255, 255, 0.82);
  --text-strong: #ffffff;
  --line: rgba(255, 255, 255, 0.15);
  --line-strong: rgba(255, 255, 255, 0.35);

  color-scheme: dark;
  font-family: "Helvetica Neue", Arial, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 17px;
  line-height: 1.75;
  color: var(--text);
  background: var(--ink);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--ink);
}

#root {
  width: 100%;
}

a {
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--text-strong);
  outline-offset: 3px;
}

.layout {
  width: 100%;
}

/* Sidebar */

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: 18em;
  height: 100vh;
  padding: 2.5em 2.5em 0.5em;
  overflow-x: hidden;
  overflow-y: auto;
  background: var(--ink);
  text-align: right;
  z-index: 100;
}

.sidebar__inner {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 100%;
  width: 100%;
}

.sidebar__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.sidebar__list li {
  margin: 1.5em 0 0;
}

.sidebar__list li:first-child {
  margin: 0;
}

.sidebar__nav a {
  display: block;
  position: relative;
  padding: 1.35em 0;
  border: 0;
  color: rgba(255, 255, 255, 0.55);
  font-size: 0.85em;
  font-weight: 700;
  letter-spacing: 0.25em;
  line-height: 1.75;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.2s ease;
}

.sidebar__nav a::before,
.sidebar__nav a::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 0.2em;
  border-radius: 0.2em;
}

.sidebar__nav a::before {
  background: #3c2c62;
}

.sidebar__nav a::after {
  background-image: linear-gradient(to right, var(--accent-from), var(--accent-to));
  max-width: 0;
  transition: max-width 0.2s ease;
}

.sidebar__nav a:hover,
.sidebar__nav a:focus-visible {
  color: var(--text-strong);
}

.sidebar__nav a:hover::after,
.sidebar__nav a:focus-visible::after {
  max-width: 100%;
}

.sidebar__nav a[aria-current="true"] {
  color: var(--text-strong);
}

.sidebar__nav a[aria-current="true"]::after {
  max-width: 100%;
}

/* Panels */

.main {
  margin-left: 18em;
}

.panel {
  position: relative;
}

.panel__inner {
  width: 75em;
  max-width: 100%;
  padding: 5em 5em 3em;
}

.panel--hero {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  background-image: linear-gradient(135deg, var(--hero-from), var(--hero-to));
}

.panel--education {
  background-color: var(--panel-education);
}

.panel--experience {
  background-color: var(--panel-experience);
}

.panel--projects {
  background-color: var(--panel-projects);
}

/* Hero */

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(1em);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.panel--hero .panel__inner {
  animation: fade-up 0.8s ease both;
}

@media (prefers-reduced-motion: reduce) {
  .panel--hero .panel__inner {
    animation: none;
  }
}

.hero__name {
  margin: 0;
  color: var(--text-strong);
  font-size: 2.75em;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.25;
}

.hero__alias {
  display: block;
  margin-top: 0.6em;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.32em;
  font-weight: 400;
  letter-spacing: 0.35em;
  text-transform: uppercase;
}

.hero__intro {
  max-width: 40em;
  margin: 1.5em 0 2em;
  color: rgba(255, 255, 255, 0.85);
  font-size: 1.15em;
}

.hero__focus-label {
  margin: 0 0 0.9em;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.8em;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.hero__focus-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7em;
  margin: 0 0 2.4em;
  padding: 0;
  list-style: none;
}

.hero__focus-item {
  padding: 0.55em 1.3em;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 3em;
  background: rgba(255, 255, 255, 0.04);
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.9em;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

.hero__focus-item:hover {
  border-color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.1);
}

/* Button */

.button {
  display: inline-block;
  position: relative;
  padding: 1em 2.6em;
  border: 1px solid var(--line-strong);
  border-radius: 3em;
  background: transparent;
  color: var(--text-strong);
  font-size: 0.85em;
  font-weight: 700;
  letter-spacing: 0.12em;
  line-height: 1.5;
  text-decoration: none;
  transition: border-color 0.2s ease;
}

.button::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 3em;
  background: var(--text-strong);
  opacity: 0;
  transform: scale(0.25);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.button:hover,
.button:focus-visible {
  border-color: rgba(255, 255, 255, 0.7);
}

.button:hover::after {
  opacity: 0.08;
  transform: scale(1);
}

/* Sections */

.section__title {
  position: relative;
  margin: 0 0 1.4em;
  padding-bottom: 0.5em;
  color: var(--text-strong);
  font-size: 1.9em;
  font-weight: 700;
  line-height: 1.5;
}

.section__title::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 4em;
  height: 0.2em;
  border-radius: 0.2em;
  background-image: linear-gradient(to right, var(--accent-from), var(--accent-to));
}

.entries {
  list-style: none;
  margin: 0;
  padding: 0;
}

.entry {
  display: grid;
  grid-template-columns: 12em minmax(0, 1fr);
  gap: 1.5em;
  padding: 1.6em 0;
