  letter-spacing: 0.05em;
  white-space: nowrap;
}

.entry__title {
  margin: 0;
  color: var(--text-strong);
  font-size: 1.2em;
  font-weight: 700;
  line-height: 1.5;
}

.entry__role {
  margin-left: 0.8em;
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.9em;
  font-weight: 400;
}

.entry__detail {
  margin: 0.5em 0 0;
  color: var(--text);
}

/* Projects */

.projects__list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.2em;
  margin: 0;
  padding: 0;
  list-style: none;
}

.project-card {
